var i=`1038-rendang`;var t=`world-1038`;var a=`ID`;var s=`southeast-asia`;var o=4;var r=285;var l={en:`Rendang`,ua:`Ренданг`};var g={en:`Rendang is a dish from Indonesia prepared with shallot, garlic, galangal, lemongrass. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Ренданг, страва кухні країни Індонезія, яку готують із таких продуктів: цибуля шалот, часник, галангал, лемонграс. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`shallot`,180,`g`],[`garlic`,7,`clove`],[`galangal`,50,`g`],[`lemongrass`,4,`pcs`],[`ground-turmeric`,7,`g`],[`ground-coriander`,8,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 135 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 135 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:135,i:[[`beef-chuck`,1050,`g`],[`coconut-milk`,950,`ml`],[`makrut-lime-leaves`,5,`leaf`],[`ceylon-cinnamon`,1,`pcs`]]},{en:`Continue slow, uncovered cooking and stir frequently as the coconut milk reduces from a stew into a thick dark coating; do not scorch the spice paste.`,ua:`Продовжуйте повільно уварювати без кришки, часто помішуючи, доки кокосове молоко не перетвориться з підливи на темне густе покриття; не підпалюйте спеції.`,t:[`reducing-sauce`],m:135,i:[[`palm-sugar`,35,`g`],[`table-salt`,null,`to_taste`],[`tamarind-concentrate`,25,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`toasted-coconut-flakes`,65,`g`]]}];var c={slug:i,id:t,country:`ID`,region:s,servings:4,minutes:285,title:l,text:g,steps:d};export{a as country,c as default,t as id,r as minutes,s as region,o as servings,i as slug,d as steps,g as text,l as title};